void main() {
  final names = ['Alice', 'Bob', 'Charlie', 'David', 'Eve'];
  for (var name in names) {
    print('Hola $name');
  }

  int fibonacci(int n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
  }

  for (int i = 0; i < 10; i++) {
    print('fibonacci($i) = ${fibonacci(i)}');
  }

  var map = {
    'nombre': 'Ssaylem',
    'lenguaje': 'Dart',
    'nivel': 'Avanzado'
  };

  map.forEach((clave, valor) {
    print('$clave: $valor');
  });

  try {
    throw Exception('Error de ejemplo');
  } catch (e) {
    print('Ocurrió un error: $e');
  }
}

